CREATE TABLE IF NOT EXISTS users(id text PRIMARY KEY,email text UNIQUE NOT NULL,password_hash text NOT NULL,name text NOT NULL,timezone text NOT NULL DEFAULT 'America/New_York',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS families(id text PRIMARY KEY,name text NOT NULL,owner_id text NOT NULL REFERENCES users(id),settings jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS memberships(id text PRIMARY KEY,family_id text NOT NULL REFERENCES families(id),user_id text NOT NULL REFERENCES users(id),role text NOT NULL CHECK(role IN('parent','student')),status text NOT NULL DEFAULT 'active',UNIQUE(family_id,user_id,role));
CREATE TABLE IF NOT EXISTS child_profiles(user_id text PRIMARY KEY REFERENCES users(id),age integer,gender text,interests text NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS chores(id text PRIMARY KEY,family_id text NOT NULL REFERENCES families(id),creator_id text NOT NULL REFERENCES users(id),title text NOT NULL,description text NOT NULL,category text NOT NULL,difficulty text NOT NULL,points integer NOT NULL,xp integer NOT NULL,recurrence text NOT NULL,requires_approval boolean NOT NULL,requires_proof boolean NOT NULL,archived_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS assignments(id text PRIMARY KEY,chore_id text NOT NULL REFERENCES chores(id),student_id text NOT NULL REFERENCES users(id),due_at timestamptz NOT NULL,status text NOT NULL CHECK(status IN('todo','pending','changes_requested','approved','rejected','completed')),awarded_submission_id text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(chore_id,student_id,due_at));
CREATE INDEX IF NOT EXISTS assignment_queue ON assignments(student_id,status,due_at);
CREATE TABLE IF NOT EXISTS submissions(id text PRIMARY KEY,assignment_id text NOT NULL REFERENCES assignments(id),attempt integer NOT NULL,note text NOT NULL,proof_url text,status text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(assignment_id,attempt));
CREATE TABLE IF NOT EXISTS decisions(id text PRIMARY KEY,submission_id text NOT NULL REFERENCES submissions(id),parent_id text NOT NULL REFERENCES users(id),decision text NOT NULL,note text NOT NULL,reversed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS point_transactions(id text PRIMARY KEY,family_id text NOT NULL REFERENCES families(id),student_id text NOT NULL REFERENCES users(id),amount integer NOT NULL,kind text NOT NULL,note text NOT NULL,reference_id text,idempotency_key text UNIQUE NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS point_ledger ON point_transactions(student_id,created_at);
CREATE TABLE IF NOT EXISTS xp_transactions(id text PRIMARY KEY,family_id text NOT NULL REFERENCES families(id),student_id text NOT NULL REFERENCES users(id),amount integer NOT NULL,kind text NOT NULL,reference_id text,idempotency_key text UNIQUE NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS daily_activity(id text PRIMARY KEY,student_id text NOT NULL REFERENCES users(id),local_date date NOT NULL,timezone text NOT NULL,qualifying_count integer NOT NULL,UNIQUE(student_id,local_date));
CREATE TABLE IF NOT EXISTS rewards(id text PRIMARY KEY,family_id text NOT NULL REFERENCES families(id),name text NOT NULL,description text NOT NULL,icon text NOT NULL,cost integer NOT NULL,stock integer NOT NULL,enabled boolean NOT NULL,requires_approval boolean NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS reward_goals(id text PRIMARY KEY,student_id text NOT NULL REFERENCES users(id),reward_id text NOT NULL REFERENCES rewards(id),active boolean NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS redemptions(id text PRIMARY KEY,reward_id text NOT NULL REFERENCES rewards(id),student_id text NOT NULL REFERENCES users(id),cost integer NOT NULL,status text NOT NULL,idempotency_key text UNIQUE NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS notifications(id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),title text NOT NULL,body text NOT NULL,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS activity_logs(id text PRIMARY KEY,family_id text NOT NULL REFERENCES families(id),actor_id text NOT NULL REFERENCES users(id),action text NOT NULL,message text NOT NULL,amount integer,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS preferences(user_id text PRIMARY KEY REFERENCES users(id),theme text NOT NULL DEFAULT 'garden',animation boolean NOT NULL DEFAULT true,reduced_motion boolean NOT NULL DEFAULT false,sound boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS achievements(id text PRIMARY KEY,name text NOT NULL,description text NOT NULL,icon text NOT NULL,threshold integer NOT NULL);
CREATE TABLE IF NOT EXISTS user_achievements(user_id text NOT NULL REFERENCES users(id),achievement_id text NOT NULL REFERENCES achievements(id),earned_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,achievement_id));
CREATE TABLE IF NOT EXISTS sessions(id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),token_hash text UNIQUE NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS invitations(id text PRIMARY KEY,family_id text NOT NULL REFERENCES families(id),email text NOT NULL,role text NOT NULL CHECK(role IN('parent','student')),status text NOT NULL DEFAULT 'pending',invited_by text NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(family_id,email,status));
